MagickBooleanType WriteImages(const ImageInfo *image_info, Image *images,
                              const char *filename, ExceptionInfo *exception)
{
  Image
    *image;

  ImageInfo
    *clone_info;

  MagickBooleanType
    status;

  ssize_t
    i;

  assert(image_info != (const ImageInfo *) NULL);
  assert(images != (Image *) NULL);
  assert(filename != (const char *) NULL);
  assert(exception != (ExceptionInfo *) NULL);

  clone_info = CloneImageInfo(image_info);
  if (clone_info == (ImageInfo *) NULL)
    return (MagickFalse);

  for (i = 0, image = images; image != (Image *) NULL; image = image->next, i++)
  {
    char
      *output_filename;

    if (image->scene == 0)
      image->scene = (size_t) (i + 1);

    output_filename = GetImageFileName(clone_info, image, filename);
    if (output_filename == (char *) NULL)
      return (MagickFalse);

    if (image->adjoin == MagickFalse)
    {
      if (WriteImage(clone_info, image, output_filename, exception) ==
          MagickFalse)
        return (MagickFalse);
    }
    else
    {
      if (WriteImage(clone_info, image, output_filename, exception) ==
          MagickFalse)
        return (MagickFalse);
    }

    (void) MagickFreeMemory(output_filename);
  }

  return (MagickTrue);
}

MagickBooleanType WriteImages(const ImageInfo *image_info, Image *images, const char *filename, ExceptionInfo *exception)
{
    Image
      *image;

    MagickBooleanType
      status;

    ImageInfo
      *clone_info;

    assert(image_info != (ImageInfo *) NULL);
    assert(images != (Image *) NULL);
    assert(filename != (const char *) NULL);
    assert(exception != (ExceptionInfo *) NULL);

    clone_info = CloneImageInfo(image_info);
    if (clone_info == (ImageInfo *) NULL)
      return(MagickFalse);

    status = MagickTrue;
    image = images;
    do
    {
      char
        *temp_filename;

      temp_filename = (char *) AcquireQuantumMemory(MaxTextExtent, sizeof(*temp_filename));
      if (temp_filename == (char *) NULL)
      {
        status = MagickFalse;
        break;
      }
      (void) FormatMagickString(temp_filename, MaxTextExtent, filename);
      if (clone_info->adjoin != MagickFalse)
      {
        status = WriteImage(clone_info, image, temp_filename, exception);
        if (status == MagickFalse)
          break;
      }
      else
      {
        Image
          *write_image;

        write_image = CloneImageList(image, exception);
        if (write_image == (Image *) NULL)
        {
          status = MagickFalse;
          break;
        }
        write_image->scene = 0;
        status = WriteImage(clone_info, write_image, temp_filename, exception);
        if (status == MagickFalse)
          break;
        write_image = DestroyImageList(write_image);
      }
      image = GetNextImageInList(image);
    } while (image != (Image *) NULL);

    clone_info = DestroyImageInfo(clone_info);
    return(status);
}

MagickBooleanType WriteImages(const ImageInfo *image_info, Image *images, const char *filename, ExceptionInfo *exception)
{
    Image
       *image;

    ImageInfo
       *write_info;

    MagickBooleanType
       status;

    ssize_t
       i;

    /* Validate input */
    if (image_info == (ImageInfo *) NULL)
      return(MagickFalse);
    if (images == (Image *) NULL)
      return(MagickFalse);
    if (filename == (const char *) NULL)
      return(MagickFalse);

    write_info = CloneImageInfo(image_info);
    if (write_info == (ImageInfo *) NULL)
      return(MagickFalse);

    status = MagickTrue;
    image = images;
    for (i = 0; i < (ssize_t) GetImageListLength(images); i++)
    {
        char
           *unique_filename;

        unique_filename = CloneString(filename);
        if (unique_filename == (char *) NULL)
        {
            status = MagickFalse;
            break;
        }

        /* Prepare filename based on scene number or other criteria */
        (void) FormatString(unique_filename, "%s-%03d", filename, i);

        /* Set up the image info for writing */
        write_info->adjoin = MagickFalse;
        image->scene = 0;

        status = WriteImage(write_info, image, unique_filename, exception);
        if (status == MagickFalse)
          break;

        /* Monitor progress if needed */
    }

    write_info = DestroyImageInfo(write_info);

    return(status);
}

MagickBooleanType WriteImages(const ImageInfo *image_info, Image *images, const char *filename, ExceptionInfo *exception) {
  Image
    *image;

  ImageInfo
    *clone_info;

  MagickBooleanType
    status;

  clone_info = CloneImageInfo(image_info);
  if (clone_info == (ImageInfo *) NULL)
    return(MagickFalse);

  status = MagickTrue;
  image = images;
  while (image != (Image *) NULL) {
    char
      *temp_filename;

    temp_filename = GetPathComponent(filename, TailPath);
    if (strlen(temp_filename) == 0)
      (void) CopyMagickString(temp_filename, filename, MaxTextLength);
    (void) FormatMagickString(clone_info->filename, MaxTextLength, "%s", temp_filename);
    (void) FormatMagickString(clone_info->filename, MaxTextLength, "%s", filename);
    if (clone_info->adjoin != MagickFalse)
      (void) SetImageScene(image, 0);
    else
      (void) SetImageScene(image, 1);
    if (WriteImage(clone_info, image, exception) == MagickFalse)
      status = MagickFalse;
    image = GetNextImageInList(image);
  }
  clone_info = DestroyImageInfo(clone_info);
  return(status);
}
